/*============================================================================
	File:		0100 - DBCC STATS_STREAM.sql

	Summary:	This script demonstrates how to update statistics in a big
				database with DBCC and STATS_STREAM option

				THIS SCRIPT IS PART OF THE TRACK: "SQL Server Statistics"

	Date:		September 2017

	SQL Server Version: 2008 / 2012 / 2014 / 2016 / 2017 / 2017
------------------------------------------------------------------------------
	Written by Uwe Ricken, db Berater GmbH

	This script is intended only as a supplement to demos and lectures
	given by Uwe Ricken.  
  
	THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF 
	ANY KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED 
	TO THE IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
	PARTICULAR PURPOSE.
============================================================================*/
USE master;
GO

IF DB_ID(N'UPD_STATS') IS NOT NULL
	DROP DATABASE UPD_STATS;
	GO


EXEC dbo.sp_create_demo_db;
GO

-- Step 1:	We create a demo table with ~280.000 records in a demo db
USE demo_db;
GO

SELECT * INTO dbo.messages
FROM sys.messages;
GO

-- Let's create an index on the severity
CREATE NONCLUSTERED INDEX ix_messages_severity
ON dbo.messages (severity);
GO

-- Now we create a second database with exactly the same structure
CREATE DATABASE UPD_STATS;
GO

USE UPD_STATS;
GO

SELECT * INTO dbo.messages FROM sys.messages;
GO

CREATE NONCLUSTERED INDEX ix_messages_severity
ON dbo.messages (severity);
GO

-- Step 2: Now we update a few records in the original database
USE demo_db;
GO

-- Stats before the update
DBCC SHOW_STATISTICS (N'dbo.messages', N'ix_messages_severity');
GO

-- Update severity 0 to 1
UPDATE	dbo.messages
SET		severity = 1
WHERE	severity = 0;
GO

-- and update the stats...
UPDATE STATISTICS dbo.messages ix_messages_severity WITH FULLSCAN;
GO

-- and check the stats again
DBCC SHOW_STATISTICS (N'dbo.messages', N'ix_messages_severity');
GO

-- Now we update the data in the second database WITHOUT updating
-- the stats!!!
USE UPD_STATS;
GO

-- Update severity 0 to 1
UPDATE	dbo.messages
SET		severity = 1
WHERE	severity = 0;
GO

-- and check the stats again
DBCC SHOW_STATISTICS (N'dbo.messages', N'ix_messages_severity');
GO

-- o.k. - we now have different statistics in 2 databases.
-- we now extract the statistics data from the first database
USE demo_db;
GO

DBCC SHOW_STATISTICS (N'dbo.messages', N'ix_messages_severity') WITH STATS_STREAM;
GO

-- copy the binary value and push it into the statistics object of the second db
USE UPD_STATS;
GO

UPDATE STATISTICS dbo.messages ix_messages_severity
WITH
	STATS_STREAM = ;
GO

DBCC SHOW_STATISTICS (N'dbo.messages', N'ix_messages_severity');
GO

/* Job done - we've updated the stats to the same values as in the first database */